// cnr — Crnogorski (montenegrino).
//
// A chave é o TEXTO EM PORTUGUÊS, exatamente como aparece no código. O que faltar aqui aparece em
// português, e não como tela vazia.
//
// POR QUE ENTROU: é a língua oficial de MONTENEGRO pela Constituição de 2007 (art. 13), e Montenegro era
// um dos membros da ONU que nenhuma língua do Syden alcançava. Se é língua própria ou variante do sérvio
// é discussão política; o Syden segue o que o país declara.
//
// DE ONDE VEIO: partiu do hr.ts, que já é latino e IJEKAVIANO (vrijeme, mlijeko) como o montenegrino, e o
// vocabulário croata foi trocado pelo de Montenegro, que é o do sérvio: računar (não računalo), server
// (não poslužitelj), pregledač, nalog (conta), podešavanja, sačuvaj, izaberi, link, dugme, ko/niko,
// tačno, tokom, futuro fundido (pročitaću). Cada linha foi relida depois da troca.
//
// ESCRITA: LATINA. A Constituição aceita latino e cirílico, e o latino é o que o país usa no dia a dia —
// e o que separa o montenegrino do sr.ts, que é cirílico. As letras próprias ś e ź existem no alfabeto
// oficial de 2009, mas são opcionais e raras na escrita corrente; este arquivo não as usa.
//
// O NAVEGADOR NÃO MANDA cnr: manda sr-Latn-ME ou sr-ME. Sem o apelido por marca inteira em
// web/src/i18n/index.ts (e em desktop/src/offline.js), quem está em Montenegro cairia no sérvio cirílico.
//
// TOM, GÊNERO, PLURAL E DECLINAÇÃO: as decisões do hr.ts valem aqui. Ti; gênero fora do passado e do
// adjetivo sobre quem lê; plural como "Poruke: {n}"; {nome} nunca colado à preposição.
//
// NÚMEROS: `Intl.NumberFormat('cnr')` devolve `1.234.567` — latinos, com ponto.
//
// O DETECTOR DO TESTE DE IDIOMAS: latino — vai o das chaves.
//
// VOCABULÁRIO, decidido uma vez: comunidade = zajednica, canal = kanal, sala de voz = glasovna soba,
// chamada = poziv, conversa = razgovor, mensagem = poruka, senha = lozinka, lixeira = koš, tópico = nit,
// conta = nalog, administrador = administrator, dono = vlasnik, cargo = uloga, convite = pozivnica,
// perfil = profil, transmissão = prenos, tela = ekran, membro = član, pacote = paket, enquete = anketa,
// denúncia = prijava, notificação e recado = obavještenje, vila = selo, guarda-roupa = garderoba,
// cutucada = bockanje.
//
// SOM E VOZ SÃO DUAS PALAVRAS: glas é a voz, zvuk é o som de soundboard e de aviso.
//
// SELO E INSÍGNIA SEPARADOS: selo = pečat (o da comunidade), insígnia = značka (a da pessoa).

