  'O Syden anuncia o prêmio no canal, e quem quiser participar reage com 🎉. Na hora marcada, ele sorteia entre quem reagiu e publica o resultado.': 'Syden objavi nagradu u kanalu, a ko želi da učestvuje reaguje sa 🎉. U zakazano vrijeme izvlači među onima koji su reagovali i objavi rezultat.',
