  'Lobisomem': 'Vukodlak',
  'À noite, escolha com os outros lobisomens quem atacar. De dia, não deixe ninguém desconfiar.': 'Noću s ostalim vukodlacima izaberi koga napasti. Danju ne daj nikome povoda za sumnju.',
  'Vidente': 'Proročište',
  'À noite, descubra se alguém é lobisomem. Conte de dia, se achar que vale o risco.': 'Noću otkrij da li je neko vukodlak. Reci to danju, ako misliš da vrijedi rizika.',
  'Anjo': 'Anđeo',
  'À noite, escolha alguém para proteger. Se os lobisomens atacarem essa pessoa, ela sobrevive.': 'Noću izaberi nekoga koga ćeš zaštititi. Ako vukodlaci napadnu tu osobu, ona preživi.',
  'Da vila': 'Iz sela',
  'À noite, durma. De dia, descubra quem são os lobisomens e vote para tirá-los do jogo.': 'Noću spavaj. Danju otkrij ko su vukodlaci i glasaj da ih izbacite iz igre.',
