  'Empate: ninguém sai hoje.': 'Neriješeno: danas niko ne izlazi.',
  'Clique em quem os lobisomens vão atacar.': 'Klikni na osobu koju će vukodlaci napasti.',
  'Você já usou a sua visão esta noite.': 'Vizija za ovu noć je već iskorišćena.',
  'Clique em alguém para descobrir se é lobisomem.': 'Klikni na nekoga da otkriješ da li je vukodlak.',
  'Clique em quem você quer proteger esta noite.': 'Klikni na osobu koju želiš da zaštitiš ove noći.',
  'Durma. Os outros papéis estão agindo.': 'Spavaj. Ostale uloge djeluju.',
  'Você saiu do jogo. Agora só assiste — sem contar nada!': 'Više nijesi u igri. Sad samo gledaš — bez odavanja!',
  'Clique em quem você quer tirar do jogo. O mais votado sai; empate, ninguém.': 'Klikni na osobu koju želiš da izbaciš iz igre. Izlazi ko ima najviše glasova; kod neriješenog niko.',
