  'Com caixa de som, pronto para o karaokê.': 'Sa zvučnikom, spreman za karaoke.',
  'Redonda, para cartas, tabuleiro e conversa.': 'Okrugao, za karte, društvene igre i razgovor.',
  'De madeira, com o assento estofado.': 'Drvena, sa tapaciranim sjedištem.',
  'Suco, refrigerante e água sempre gelados.': 'Sok, gazirano piće i voda, uvijek hladni.',
  'A cozinha da turma. O botão direito acende e apaga o fogão.': 'Kuhinja društva. Desni klik pali i gasi šporet.',
  'Um pufe enorme, para afundar e ficar.': 'Ogroman puf da u njega utoneš i ostaneš.',
  'Pendurado no gancho, esperando a próxima call.': 'Okačene o kuku, čekaju sljedeći poziv.',
  'Fotos dos amigos presas num varal.': 'Fotografije prijatelja okačene na kanapu.',
  'Recados e ideias presos com alfinete.': 'Poruke i ideje zakačene čiodama.',
  'Livros, uma plantinha e um vaso.': 'Knjige, biljčica i vaza.',
  'Um pôr do sol sobre os campos.': 'Zalazak sunca nad poljima.',
  'Xícaras, potes e garrafas de suco.': 'Šolje, tegle i flaše soka.',
  'Potes de biscoito e pipoca para dividir.': 'Tegle keksa i kokica za dijeljenje.',
  'As taças das vitórias da turma.': 'Pehari pobjeda društva.',
  'Um coelho de neon que brilha no escuro.': 'Neonski zec koji svijetli u mraku.',
  'Um relógio de madeira para ninguém perder a hora.': 'Drveni sat, da niko ne zaboravi koliko je sati.',
  'Para quem quiser puxar uma música.': 'Za svakog ko želi da zapjeva.',
  'Dá no banheiro. Bata antes de entrar.': 'Vodi u kupatilo. Pokucaj prije ulaska.',
  'O cartaz do karaokê, em três versões: palco, neon e fogo.': 'Plakat za karaoke, u tri verzije: bina, neon i vatra.',
  'Dois coelhos, um café e a fofoca do dia.': 'Dva zeca, jedna kafa i dnevni tračevi.',
  'Café quentinho, ainda soltando fumaça.': 'Topla kafa, još se puši.',
  'Suco de laranja com canudinho.': 'Sok od pomorandže sa slamčicom.',
  'Uma lata gelada.': 'Hladna limenka.',
  'Uma suculenta pequena, que quase não pede água.': 'Mali sukulent kojem skoro ne treba voda.',
  'Uma pilha de livros para ler depois.': 'Gomila knjiga za kasnije.',
  'O console da turma, com o controle ao lado.': 'Konzola društva, sa džojstikom pored.',
  'Um balde de pipoca para ver a transmissão.': 'Kofa kokica za gledanje prenosa.',
