  'Escreva o começo do nome e escolha da lista.': 'Ukucaj početak imena i izaberi sa liste.',
  'Seu chute': 'Tvoj odgovor',
  'Chutes: {n}': 'Pokušaji: {n}',
  'Monstros de fantasia': 'Fantastična čudovišta',
  'Sai um monstro secreto, e cada um chuta outros da lista. Cada chute mostra o que bate com o secreto: tipo, tamanho, nível, alinhamento e como ele se desloca. Quem acertar com menos chutes ganha mais pontos.': 'Izvlači se tajno čudovište, a svi pogađaju druga sa liste. Svaki pokušaj pokazuje šta se poklapa sa tajnim: tip, veličina, nivo, opredjeljenje i kako se kreće. Ko pogodi iz manje pokušaja, dobija više poena.',
  'Sai uma figura secreta da mitologia, e cada um chuta outras. Cada chute mostra o que bate com a secreta: a mitologia, o tipo, a forma e o que ela governa. Quem acertar com menos chutes ganha mais pontos.': 'Izvlači se tajna ličnost iz mitologije, a svi pogađaju druge. Svaki pokušaj pokazuje šta se poklapa sa tajnom: mitologija, tip, oblik i čime vlada. Ko pogodi iz manje pokušaja, dobija više poena.',
  'Países': 'Države',
  'Sai um país secreto, e cada um chuta outros. Cada chute mostra a distância e a direção até o secreto, a região, a sub-região e a população. Quem acertar com menos chutes ganha mais pontos.': 'Izvlači se tajna država, a svi pogađaju druge. Svaki pokušaj pokazuje udaljenost i smjer do tajne države, region, podregion i stanovništvo. Ko pogodi iz manje pokušaja, dobija više poena.',
