  'Empurre os outros para fora do canteiro. A borda que pisca vai cair!': 'Guraj ostale iz leje. Ivica koja treperi će pasti!',
  'Corrida de cavalinho': 'Trka na konjiću',
  'Alterne ← e → no ritmo. Com pressa demais, o fôlego acaba.': 'Naizmjenično ← i → u ritmu. Ako požuriš, ponestaće daha.',
  'Cartas do celeiro': 'Karte iz štale',
  'Na sua vez, vire uma carta ou guarde as cenouras. A raposa leva tudo!': 'U svom potezu okreni kartu ili sačuvaj šargarepe. Lisica nosi sve!',
  'Chuva de cenouras': 'Kiša šargarepa',
  'Desça pegando as cenouras. Das pedras, fuja!': 'Spuštaj se i kupi šargarepe. Od kamenja — bježi!',
  'De galho em galho': 'S grane na granu',
  'Solte o cipó quando ele estiver na faixa clara.': 'Pusti lijanu kad je u svijetloj traci.',
  'Colheita em dupla': 'Berba u paru',
  'Em dupla: quem está no galho solta os morangos maduros, e quem está embaixo apanha com a cesta.': 'U paru: ko je na grani pušta zrele jagode, a ko je dolje hvata ih korpom.',
  'Baile da toca': 'Bal u jazbini',
  'Guarde a ordem da dança. No fim, diga quem dançou na lâmpada marcada.': 'Zapamti redosljed plesa. Na kraju reci ko je plesao na označenoj lampi.',
  'Chão que desmorona': 'Pod koji se ruši',
  'A tábua racha quando alguém para em cima. Continue andando e empurre os outros para a água!': 'Daska puca kad neko stane na nju. Nastavi da hodaš i guraj ostale u vodu!',
  'Arrume a despensa': 'Sredi ostavu',
  'Guarde onde fica cada pote e ponha todos de volta no lugar.': 'Zapamti đe stoji svaka tegla i vrati ih sve na mjesto.',
  'Esconde-esconde na horta': 'Žmurke u bašti',
  'Esconda-se onde a lanterna não vai olhar. Quem tem a lanterna procura!': 'Sakrij se tamo đe baterijska lampa neće pogledati. Ko ima lampu, traži!',
  'Três flechas': 'Tri strijele',
  'A flecha sobe reta e fura o que encontrar. Os balões pequenos valem mais.': 'Strijela ide pravo gore i buši sve na šta naiđe. Mali baloni vrijede više.',
  'Bate quando der a flor': 'Lupi na cvijet',
  'Bata quando aparecer a flor igual à do quadrinho. Na figura errada, está fora.': 'Lupi kad se pojavi cvijet isti kao u okviru. Na pogrešnoj slici ispadaš.',
  'Foguete de cenoura': 'Raketa od šargarepe',
  'Bombeie quando o anel acender. Fora do ritmo, o ar escapa.': 'Pumpaj kad se prsten upali. Van ritma — vazduh izlazi.',
  'Pegue a galinha': 'Uhvati kokošku',
  'Encurrale a galinha. Cansada, ela fica lenta.': 'Saćeraj kokošku u ćošak. Umorna, postaje spora.',
  'Repolhos no gelo': 'Kupus na ledu',
  'Pegue as cenouras no gelo e fuja dos repolhos.': 'Kupi šargarepe na ledu i bježi od kupusa.',
  'Abóboras ladeira abaixo': 'Bundeve nizbrdo',
  'Lá de cima rolam abóboras; quem sobe troca de faixa para fugir delas!': 'Odozgo se kotrljaju bundeve; ko se penje mijenja traku da im pobjegne!',
  'Quem está atrás da turma?': 'Ko je iza gomile?',
  'Descubra quem está escondido. Uma chance só: quanto antes, mais vale.': 'Otkrij ko se krije. Samo jedan pokušaj: što ranije, to više vrijedi.',
  'Arremesso do nabo': 'Bacanje repe',
  'Solte quando o nabo apontar para o campo. Girando mais rápido, vai mais longe.': 'Pusti kad repa pokazuje ka polju. Što se brže vrti, to dalje leti.',
  'Onda no açude': 'Talas na bari',
  'Quem está no remo manda ondas; quem está na jangada pula na hora!': 'Ko je na veslu šalje talase; ko je na splavu skače na vrijeme!',
  'Pula o ponteiro': 'Preskoči kazaljku',
  'Pule quando o ponteiro passar. Ele fica cada vez mais rápido.': 'Skoči kad kazaljka prođe. Sve je brža.',
  'Ponte do riacho': 'Most preko potoka',
  'Leve as três tábuas até a ponte. Cuidado com as pedras que afundam!': 'Odnesi tri daske do mosta. Pazi na kamenje koje tone!',
  'Quem está em qual toca?': 'Ko je u kojoj jazbini?',
  'Siga os bichos de toca em toca. No fim, aponte onde está o do balão.': 'Prati životinjice od jazbine do jazbine. Na kraju pokaži đe je ona iz oblačića.',
  'As chaves da porteira': 'Ključevi kapije',
  'Pegue uma cenoura dourada e leve até a porteira. Falta uma: empurre quem estiver carregando!': 'Uzmi zlatnu šargarepu i odnesi je do kapije. Jedna fali: gurni onoga ko je nosi!',
  'Destampe os potes': 'Otvori tegle',
  'Gire cada tampa para o lado da seta, depressa. O lado errado aperta de novo.': 'Okreni svaki poklopac na stranu strelice, brzo. Pogrešna strana ga opet steže.',
  'Praga na toca': 'Štetočine u jazbini',
  'Bata nas lagartas que saírem das tocas. No coelhinho, não!': 'Lupaj gusjenice koje izlaze iz rupa. Samo ne zečića!',
  'Rebater o rabanete': 'Odbij rotkvicu',
  'Rebata quando o rabanete chegar à base. Bem na hora, vai mais longe.': 'Odbij kad rotkvica stigne do baze. Tačno na vrijeme — leti dalje.',
  'Regar a horta': 'Zalij baštu',
  'Leve a nuvem até o canteiro com sede.': 'Odvedi oblačić do žedne leje.',
  'Qual destes cresce debaixo da terra?': 'Šta od ovoga raste pod zemljom?',
  'Quantas orelhas tem um coelho?': 'Koliko ušiju ima zec?',
  'Duas': 'Dva',
  'Três': 'Tri',
  'Quatro': 'Četiri',
