  'Terno': 'Odijelo',
  'Moletom': 'Duks',
  'Qual destes é uma ferramenta da horta?': 'Šta je od ovoga alat za baštu?',
  'Travesseiro': 'Jastuk',
  'Regador': 'Kanta za zalivanje',
  'Do que uma planta precisa para crescer?': 'Šta je biljci potrebno da raste?',
