  'Minigolfe 3D': 'Minigolf 3D',
  'Oito buracos em 3D, com rampas, castelo e moinho, todos jogando o mesmo ao mesmo tempo. Arraste para mirar e dar a força, e solte. Ganha quem somar menos tacadas.': 'Osam rupa u 3D, sa rampama, zamkom i vjetrenjačom, svi igraju istu u isto vrijeme. Povuci za nišanjenje i snagu, pa pusti. Pobjeđuje onaj sa najmanje udaraca ukupno.',
  'Ver o buraco de cima': 'Pogledaj rupu odozgo',
  'Fora da pista! Mais uma tacada.': 'Van staze! Još jedan udarac.',
  'Arraste para o lado para mirar e para baixo para a força, e solte. No teclado: as setas miram, e o Espaço segurado dá a força.': 'Povuci u stranu za nišanjenje i nadolje za snagu, pa pusti. Na tastaturi: strelice nišane, a držanje Razmaknice daje snagu.',
  'Futebol dos coelhos': 'Zečji fudbal',
  'Futebol de campo pequeno, visto de cima. Encoste na bola para conduzir, segure Espaço para chutar mais forte e passe com X. Na sala, os times se completam com robôs.': 'Fudbal na malom terenu, gledan odozgo. Dotakni loptu da je vodiš, drži Razmaknicu za jači šut i dodaj sa X. U sobi se timovi popunjavaju robotima.',
