  'Caça às pragas da horta': 'Lov na štetočine u bašti',
  'Corvos e gafanhotos atacam a horta. Mire e clique para acertar antes que fujam: a munição é contada, e cada onda vem mais rápida. Ganha quem fizer mais pontos.': 'Vrane i skakavci napadaju baštu. Nišani i klikni da ih pogodiš prije nego što pobjegnu: municija je odbrojana, a svaki talas dolazi brže. Pobjeđuje onaj ko skupi najviše poena.',
  'Mire e clique nas pragas antes que fujam. Cada tiro gasta uma cenoura.': 'Nišani i klikni na štetočine prije nego što pobjegnu. Svaki hitac troši jednu šargarepu.',
