  'Setas para correr, Espaço para pular (segure para ir mais alto).': 'Strelice za trčanje, Razmaknica za skok (drži za viši skok).',
  'Nenhum amigo jogou esta fase ainda.': 'Ovaj nivo još niko od prijatelja nije igrao.',
  'Chuva na horta: todo mundo ganha {n} cenouras.': 'Kiša u bašti: svi dobijaju {n} šargarepa.',
