  'Ande pelas capitais do Brasil, compre cidades e cobre aluguel de quem parar nelas. Com uma região inteira, dá para construir prédios. Troque, dispute nos leilões e não fique sem dinheiro.': 'Idi kroz prijestonice Brazila, kupuj gradove i naplaćuj kiriju od onih koji na njima stanu. S cijelim regionom možeš da gradiš zgrade. Mijenjaj, nadmeći se na aukcijama i nemoj da ostaneš bez novca.',
