  'No app do Syden, o recorte funciona com qualquer fundo.': 'U Syden aplikaciji uklanjanje radi sa bilo kojom pozadinom.',
  'O recorte com o modelo falhou, e ficou o recorte simples.': 'Uklanjanje pomoću modela nije uspjelo, pa je korišćeno jednostavno.',
  'Mandar figurinha': 'Pošalji naljepnicu',
  'Tirar figurinha': 'Ukloni naljepnicu',
  'Crie figurinhas com as suas imagens, ou salve as que receber numa conversa.': 'Pravi naljepnice od svojih slika ili sačuvaj one koje dobiješ u razgovoru.',
