  'Damas': 'Dama',
  'Batalha naval': 'Potapanje brodova',
  'O dominó de sempre, de 2 a 4 pessoas (com 4, em duplas). Encaixe as pedras pelas pontas, e quem bater primeiro leva os pontos das mãos dos outros.': 'Klasične domine za 2 do 4 igrača (s četvoro u parovima). Slaži pločice na krajeve, a ko se prvi riješi svih, uzima bodove iz ruku ostalih.',
  'O truco paulista, com vira e manilha, em 2 ou em duplas de 4. Peça truco, aumente para seis, nove e doze, ou corra. Ganha quem fizer 12 pontos.': 'Truco iz São Paula, s okrenutom kartom i adutima, u dvoje ili u dva para. Zovi truco, digni na šest, devet i dvanaest ili bježi. Pobjeđuje ko skupi 12 bodova.',
  'As damas brasileiras: comer é obrigatório, para a frente e para trás, e a dama anda a diagonal inteira. A sala assiste.': 'Brazilska dama: uzimanje je obavezno, naprijed i nazad, a dama ide cijelom dijagonalom. Soba gleda.',
  'Cada um esconde a sua frota e atira no mar do outro. Acertou, atira de novo. Vence quem afundar a frota inteira primeiro. A sala assiste.': 'Svako sakrije svoju flotu i gađa more drugoga. Ako pogodiš, gađaš ponovo. Pobjeđuje ko prvi potopi cijelu flotu. Soba gleda.',
