  Bispo: 'Lovac',
  'Cozinha da toca': 'Kuhinja jazbine',
  'Pegue os ingredientes nos caixotes, pique na tábua, cozinhe no fogão e no forno sem queimar, monte no prato e entregue na janela. Todos recebem os mesmos pedidos: ganha quem entregar mais pratos em 3 minutos.': 'Uzmi sastojke iz sanduka, isjeckaj ih na dasci, skuvaj na šporetu i u rerni da ne zagore, složi na tanjir i predaj na prozoru. Svi dobijaju iste porudžbine: pobjeđuje ko preda najviše tanjira za 3 minuta.',
  'Pegar ou largar': 'Uzmi ili spusti',
  'Este jogo precisa de gráficos 3D, que não abriram neste aparelho.': 'Ovoj igri trebaju 3D grafike, koje se nijesu otvorile na ovom uređaju.',
  'Este prato não é o pedido.': 'Ovaj tanjir nije porudžbina.',
