  "Registros limitados de Docker, SSH, logind e kernel dos três boots mais recentes. Podem conter endereços IP.": "Ograničeni zapisi Docker-a, SSH-a, logind-a i jezgra iz posljednja tri pokretanja. Mogu sadržati IP adrese.",
  "Atualizar diagnóstico": "Osvježi dijagnostiku",
  "Ainda não há snapshot. Ele será coletado na próxima abertura do cofre.": "Još nema snimka. Biće prikupljen pri sljedećem otvaranju sefa.",
  "Coletado em {data}": "Prikupljeno {data}",
