  "Os mesmos números do painel do provedor. Inclui o disco, que o servidor não mede sozinho.": "Isti brojevi kao na kontrolnoj tabli dobavljača. Uključuje disk, koji server sam ne mjeri.",
  "Ações no servidor": "Radnje na serveru",
  "O histórico da Hetzner: ligar, desligar e reiniciar, pelo painel ou pela API. Uma queda sem ação aqui não foi comandada por esses caminhos.": "Istorija u Hetzner-u: uključivanje, isključivanje i ponovno pokretanje, sa table ili preko API-ja. Prekid bez radnje ovdje nije pokrenut tim putevima.",
