  // O fundo da câmera (16/11/2026)
  'Fundo da câmera': "Pozadina kamere",
  'Desfocado': "Zamuti",
  'Desfoca, apaga ou troca o que aparece atrás de você. A imagem da câmera não sai do computador para isso.': "Zamućuje, briše ili mijenja ono što se vidi iza tebe. Slika s kamere zbog toga ne napušta tvoj računar.",
  // A transmissão personalizada (16/11/2026)
  'Nativa': "Izvorna",
  'Resolução': "Rezolucija",
  'Quadros por segundo': "Sličica u sekundi",
  'Para quando a escolha automática errar: a resolução e os quadros ficam os que você escolher, do começo ao fim da transmissão.': "Za kada automatski izbor pogriješi: rezolucija i sličice ostaju kakve izabereš, od početka do kraja prenosa.",
  // O Syden Broadcast (16/11/2026)
  'Os efeitos de voz e de câmera feitos no seu computador, sem enviar nada a um servidor.': "Efekti za glas i kameru koji se rade na tvom računaru, bez slanja bilo čega na server.",
  // O Comando Cenoura (16/11/2026)
  'Comando Cenoura': "Komandos Šargarepa",
  'Correr e atirar com a turma: o lança-cenouras mira em oito direções, a granada abre caminho e quem solta os coelhinhos presos ganha reforço. O dragão espera no fim: de 1 a 4 pessoas.': "Trči i pucaj s društvom: bacač šargarepa nišani u osam pravaca, granata otvara put, a ko oslobodi zatvorene zečiće dobija pojačanje. Zmaj čeka na kraju: od 1 do 4 osobe.",
  'Andar e mirar': "Hodaj i nišani",
  'Granada': "Granata",
  // A Masmorra da Toca (16/11/2026)
  'Masmorra da Toca': "Tamnica jazbine",
  'Atravessem juntos a toca do rei-cogumelo: salas cheias de bichos, um baú com a cenoura que vai e volta, botões que pedem dois ao mesmo tempo e a porta trancada. De 1 a 4 pessoas.': "Pređite zajedno jazbinu kralja-pečurke: sobe pune životinjica, škrinja sa šargarepom koja ide i vraća se, dugmad koja traže dvoje u isto vrijeme i zaključana vrata. Od 1 do 4 osobe.",
  // O Ringue da Toca (16/11/2026)
  'Ringue da Toca': "Ring kod jazbine",
  'Boxe de reflexo contra três adversários do computador. Leia o aviso de cada golpe, esquive ou defenda e bata na brecha. Bater quando a luva brilha enche a estrela do soco forte.': "Boks refleksa protiv tri protivnika iz računara. Čitaj najavu svakog udarca, izmakni se ili se brani i udri u otvor. Udarac dok rukavica sija puni zvijezdu jakog udarca.",
  'Esquivar': "Izmakni se",
  'Abaixar e defender': "Sagni se i brani",
  'Socar': "Udri",
  'Soco forte': "Jak udarac",
  'Aperte os socos para levantar!': "Pritiskaj udarce da ustaneš!",
  'Lutas vencidas: {n}': "Dobijene borbe: {n}",
  'Nocaute!': "Nokaut!",
  // A Rota Estelar (16/11/2026)
  'Rota Estelar': "Zvjezdana ruta",
  'Coelhos em naves pela superfície de um planeta e pelo espaço: atire, segure o tiro para travar a mira, gire para desviar dos tiros e escolha o caminho na bifurcação. A turma voa a mesma rota, e o chefe espera no fim.': "Zečevi u svemirskim brodovima preko površine planete i kroz svemir: pucaj, drži pucanj da zaključaš metu, okreni se da odbiješ hice i izaberi put na račvanju. Ekipa leti istom rutom, a gazda čeka na kraju.",
  'Pirueta': "Okret",
  'Segure para travar a mira': "Drži da zaključaš metu",
  // O Pinball da Horta (16/11/2026)
  'Pinball da Horta': "Fliper u bašti",
  'Uma mesa de pinball na horta: segure a mola, rebata nos repolhos e derrube as três cenouras para acender a toca do coelho, que solta mais uma bola. Três bolas, e sacudir demais trava a mesa.': "Fliper sto u bašti: drži oprugu, odbijaj se od kupusa i obori tri šargarepe da upališ zečju jazbinu, koja pušta još jednu lopticu. Tri loptice, a previše drmanja zaključava sto.",
  'Palhetas': "Flipovi",
  'Mola': "Opruga",
  'Sacudir': "Prodrmaj",
  'Bola salva!': "Loptica spašena!",
  'Multibola!': "Više loptica!",
  'Mesa travada!': "Sto zaključan!",
  'Cuidado!': "Pazi!",
  'Recordes dos amigos': "Rekordi prijatelja",
  // O Planador da toca (16/11/2026)
  'Planador da toca': 'Jazbinska jedrilica',
  'Desafios de voo: asa-delta, mochila a jato e paraquedas. Passe pelos anéis e pouse no alvo, perto do centro e de leve.': 'Letački izazovi: zmaj, mlazni ranac i padobran. Prođi kroz prstenove i sleti na metu, blizu centra i nježno.',
