  'Um RPG de turnos curto: cada um controla um herói da turma. Escolham juntos, combinem ataques e vençam o dragão do castelo.': "Kratki RPG na poteze: svako upravlja jednim junakom družine. Birajte zajedno, kombinujte napade i pobijedite zmaja iz zamka.",
