  'Bichos da Toca': "Životinjice iz jazbine",
  'Ande pelo campo, faça amizade com os bichos do mato usando uma cenoura e monte uma equipe de até seis. Vença o desafio da casa azul e, na sala, lute com a equipe de um amigo.': "Lutaj livadama, sprijatelji se šargarepom sa životinjicama iz visoke trave i složi ekipu do šest. Savladaj izazov u plavoj kući, a u sobi se bori protiv ekipe prijatelja.",
