  "A armadilha de {nome} disparou: quem sai junto?": "{nome} aktivira zamku: ko izlazi zajedno?",
  "A largada precisa de uma reta.": "Za start je potreban pravac.",
  "A Maravilha de {nome} ficou de pé por 2 minutos.": "{nome}: Čudo je stajalo 2 minuta.",
  "A mesma posição pela terceira vez empata, e 20 lances só de dama sem comer também.": "Ista pozicija po treći put je remi, kao i 20 poteza samo damama bez uzimanja.",
  "À noite, veja quem os lobisomens atacaram. Uma poção salva essa pessoa e outra tira alguém do jogo; cada uma vale uma vez.": "Noću vidi koga su vukodlaci napali. Jedan napitak spašava tu osobu, a drugi izbacuje nekoga iz igre; svaki važi jednom.",
  "A partida se desencontrou entre os computadores e foi encerrada.": "Računari su izgubili sinhronizaciju, pa je partija prekinuta.",
  "A pedra que termina o lance na última fileira vira dama, que anda a diagonal inteira.": "Figura koja završi potez u posljednjem redu postaje dama, koja ide cijelom dijagonalom.",
  "A pista ainda não fecha a volta.": "Staza još ne zatvara krug.",
