  "A turma está decidindo.": "Društvo odlučuje.",
  "A turma inteira leva bem menos dano nesta rodada.": "Cijelo društvo prima mnogo manje štete u ovoj rundi.",
  "A turma recupera vida no fim de três rodadas.": "Društvo obnavlja život na kraju sljedeće tri runde.",
