  // Os mini-games e as insígnias (19/11/2026)
  "{nome} terminou uma Maravilha: defenda-a por 2 minutos!": "{nome} završava Čudo: brani ga 2 minuta!",
  "{nome} terminou uma Maravilha.": "{nome} završava Čudo.",
  "A Maravilha da outra equipe ficou de pé por 2 minutos.": "Čudo druge ekipe je stajalo 2 minuta.",
