  "Duas equipes de dois. Os robôs completam os lugares que faltam.": "Dvije ekipe po dvoje. Roboti popunjavaju prazna mjesta.",
  "Gênero": "Pol",
  "Levadiça": "Pokretni most",
  'Nenhuma conversa ainda. Toque em alguém na lista de pessoas da comunidade e escolha "Enviar mensagem".': "Još nema razgovora. Dodirni nekoga na spisku članova zajednice i izaberi „Pošalji poruku”.",
  "Varia": "Različito",
  "Vitória de {nomes}": "Pobjeda: {nomes}",
  "Vocês derrubaram os dois centros da vila da outra equipe.": "Tvoja ekipa je srušila oba centra sela druge ekipe.",
  // Os mini-games e as insígnias (19/11/2026)
  "A cidade que ninguém compra vai a leilão. Hipotecar uma cidade dá dinheiro, mas ela não cobra aluguel.": "Grad koji niko ne kupi ide na aukciju. Hipotekovan grad donosi novac, ali ne naplaćuje kiriju.",
  "A dica acende a peça que move. O problema com dica não pontua; na corrida, ela tira 10 segundos.": "Pomoć osvijetli figuru koja treba da se pomjeri. Zadatak s pomoći ne donosi bodove, a u trci pomoć oduzima 10 sekundi.",
  "A manilha é o valor seguinte ao da vira e ganha de todas. Entre elas: ouros, espadas, copas e paus, o zap.": "Adut je sljedeća vrijednost poslije okrenute karte i bije sve ostale. Među njima: karo, pik, herc i tref — zap.",
  "A última nave de cada volta sai.": "Posljednji brod u svakom krugu ispada.",
  "Abaixar": "Sagni se",
  "Acertos em sequência: {n}": "Riješeno zaredom: {n}",
  "Ande pelo dado e compre a capital onde parar. Quem para na cidade de outro paga aluguel.": "Idi po kocki i kupi prijestonicu đe staneš. Ko stane na tuđi grad, plaća kiriju.",
  "Cada linha, coluna e bloco de 3 × 3 tem os números de 1 a 9, sem repetir.": "Svaki red, kolona i blok 3 × 3 ima brojeve od 1 do 9, bez ponavljanja.",
  "Cada um recebe 3 cartas. Leva a mão quem ganhar 2 das 3 rodadas.": "Svako dobija 3 karte. Ruku nosi ko dobije 2 od 3 runde.",
  "Campeonato": "Šampionat",
  "Com 11 pontos, a dupla vê as cartas e decide se joga a mão de onze. Vence quem chegar a 12.": "Sa 11 bodova par gleda karte i odlučuje da li igra ruku od jedanaest. Pobjeđuje ko stigne do 12.",
  "Com a região inteira, construa até 4 prédios: o aluguel sobe a cada um.": "Sa cijelim regionom gradi do 4 zgrade: kirija raste sa svakom.",
  "Com estrelas, o soco forte (★) gasta todas de uma vez e dói mais.": "Jak udarac (★) troši sve zvijezde odjednom i više boli.",
  "Dica": "Pomoć",
  "Dica: este problema não pontua": "Pomoć: ovaj zadatak ne donosi bodove",
  "Dica: tira 10 segundos": "Pomoć: minus 10 sekundi",
  "Eliminação": "Eliminacija",
  "Encoste uma pedra numa ponta da mesa com o mesmo número.": "Prisloni pločicu na kraj stola sa istim brojem.",
  "Escolha a casa e depois o número. O lápis anota só para você.": "Izaberi polje, pa broj. Bilješke olovkom vidiš samo ti.",
  "Esquive do golpe e soque logo depois: é o contra-ataque, e vale estrela.": "Izmakni se udarcu i odmah udri: to je kontranapad i donosi zvijezdu.",
  "Fora da corrida na volta {n}.": "Van trke u krugu {n}.",
  "Força das cartas": "Jačina karata",
  "Ganha o maior patrimônio no fim das rodadas, ou quem sobrar.": "Pobjeđuje najveća imovina na kraju rundi, ili ko posljednji ostane.",
  "Iniciante": "Početnik",
  "Mestre": "Majstor",
  "Na sequência, cada acerto traz um problema mais difícil, e o primeiro erro acaba.": "U nizu svaki pogodak donosi teži zadatak, a prva greška ga završava.",
  "O número pequeno no botão diz quantos ainda faltam.": "Mali broj na dugmetu pokazuje koliko ih još fali.",
  "Os cinco traçados seguidos contra o computador, com pontos.": "Pet staza zaredom protiv računara, sa bodovima.",
  "Peça truco e a mão vale 3. Quem responde aceita, corre ou aumenta para 6, 9 ou 12.": "Zovi truco i ruka vrijedi 3. Ko odgovara prihvata, bježi ili diže na 6, 9 ili 12.",
  "Quem bate fica sem pedras e leva os pontos das mãos dos outros. Trancado, leva quem tem menos pontos na mão.": "Ko izađe ostaje bez pločica i uzima bodove iz ruku ostalih. Kad je igra blokirana, uzima onaj sa najmanje bodova u ruci.",
  "Sem pedra que sirva, compre. Sem nada para comprar, a vez passa.": "Bez pločice koja odgovara, vuci. Kad nema šta da se vuče, red prelazi dalje.",
  "Sequência": "Niz",
  "Soque quando a luva brilhar: o golpe para e você ganha uma estrela.": "Udri kad rukavica zasija: udarac staje i dobijaš zvijezdu.",
  "Treino livre": "Slobodan trening",
  // Os mini-games e as insígnias (19/11/2026)
  "{n} capitais": "Prijestonice: {n}",
  "{nome} aprendeu {golpe}!": "{nome} zna novi napad: {golpe}!",
  "{nome} deu {bicho} para você cuidar.": "{nome} ti povjerava na brigu: {bicho}.",
  "{nome} esqueceu {antigo} e aprendeu {golpe}.": "{nome}: umjesto {antigo} sada zna {golpe}.",
  "{nome} parou com tudo valendo: +{n}": "{nome} viče STOP i svi odgovori važe: +{n}",
  "{nome} quer aprender {golpe}, mas já sabe 4 golpes.": "{nome} želi da nauči {golpe}, ali već zna 4 napada.",
  "{nome} tomou erva-doce e ficou bem.": "{nome} dobija morač i opet je dobro.",
  "{nome} vai voltar para o mato. Tem certeza?": "{nome} se vraća u travu. Sigurno?",
  "A geladeira pifou: pague {valor}.": "Pokvario se frižider: plati {valor}.",
  "A pedra não come para trás": "Kamen ne jede unazad",
  "A restituição do imposto caiu na conta: receba {valor}.": "Povraćaj poreza legao je na račun: primi {valor}.",
  "A toca está vazia.": "Jazbina je prazna.",
  "A turma fez uma vaquinha: cada um te dá {valor}.": "Društvo je skupilo pare: svako ti daje {valor}.",
  "Aceitar que não vale": "Prihvati da ne važi",
  "Achou um atalho: avance 5 casas.": "Prečica: idi 5 polja naprijed.",
  "Alta temporada em {lugares}: os aluguéis dobram por uma rodada.": "Glavna sezona ({lugares}): kirije se udvostručuju na jednu rundu.",
  "As duas diagonais também têm os números de 1 a 9.": "I obje dijagonale imaju brojeve od 1 do 9.",
  "As escuras não fazem dois três abertos de uma vez": "Crni ne prave dvije otvorene trojke odjednom",
  "As escuras não podem fazer dois três abertos de uma vez.": "Crni ne smiju da naprave dvije otvorene trojke odjednom.",
  "Baixa temporada em {lugares}: os aluguéis caem pela metade por uma rodada.": "Van sezone ({lugares}): kirije padaju na pola na jednu rundu.",
  "Batidas especiais: carroça e lá-e-ló valem o dobro": "Posebni završeci: dupla i kamen za oba kraja vrijede duplo",
  "Brasil inteiro": "Cijeli Brazil",
  "Captura: cercar duas pedras do outro tira as duas": "Hvatanje: opkoljavanje dva protivnička kamena uklanja oba",
  "Carroça!": "Dupla!",
  "Cenoura dourada": "Zlatna šargarepa",
  "Chá forte": "Jak čaj",
  "Chegou o IPTU: pague {valor} por cidade sua.": "Stigao je porez na imovinu: plati {valor} za svaki svoj grad.",
  "Chuva de estrelas": "Kiša zvijezda",
  "Com a captura, cercar duas pedras do outro entre duas suas tira as duas; cinco capturas também vencem.": "Sa hvatanjem: dva protivnička kamena između dva tvoja uklanjaju se oba; pet hvatanja takođe pobjeđuje.",
  "Com a restrição 3-3, as escuras não podem fazer dois três abertos de uma vez.": "Sa ograničenjem 3-3 crni ne smiju da naprave dvije otvorene trojke odjednom.",
  "Com as batidas especiais, bater com carroça ou com a pedra que serve nas duas pontas vale o dobro; a carroça nas duas pontas, o quádruplo.": "Sa posebnim završecima, završiti duplom ili kamenom koji pristaje na oba kraja vrijedi duplo; dupla na oba kraja četvorostruko.",
  "Consulta no dentista: pague {valor}.": "Pregled kod zubara: plati {valor}.",
  "Copa do Celeiro": "Kup štale",
  "Cruzada!": "Unakrst!",
