  "Saara": "Sahara",
  "Sai um animal secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a classe, a dieta, onde ele vive e o peso. Quem acertar com menos chutes ganha mais pontos.": "Izvuče se tajna životinja, a svako pogađa druge. Svaki pokušaj pokaže šta se poklapa sa tajnom: klasa, ishrana, gdje živi i težina. Ko pogodi sa manje pokušaja, dobija više poena.",
  "Sai um dinossauro secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: o período, a dieta, o grupo, o comprimento e onde ele foi achado. Quem acertar com menos chutes ganha mais pontos.": "Izvuče se tajni dinosaurus, a svako pogađa druge. Svaki pokušaj pokaže šta se poklapa sa tajnim: period, ishrana, grupa, dužina i gdje je pronađen. Ko pogodi sa manje pokušaja, dobija više poena.",
  "Sai um elemento químico secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a família, o estado físico, o período, o grupo e o número atômico. Quem acertar com menos chutes ganha mais pontos.": "Izvuče se tajni hemijski element, a svako pogađa druge. Svaki pokušaj pokaže šta se poklapa sa tajnim: porodica, agregatno stanje, period, grupa i atomski broj. Ko pogodi sa manje pokušaja, dobija više poena.",
  "Sai um estado secreto do Brasil, e cada um chuta outros. Cada chute mostra a distância e a direção até o secreto, a região, a população, a área, o litoral e a fronteira com outro país. Quem acertar com menos chutes ganha mais pontos.": "Izvuče se tajna savezna država Brazila, a svako pogađa druge. Svaki pokušaj pokaže udaljenost i smjer do tajne, region, stanovništvo, površinu, obalu i granicu sa drugom zemljom. Ko pogodi sa manje pokušaja, dobija više poena.",
